<template>
  <div class="page-heading"><div><h1 class="page-title">推广数据同步设置</h1><p>设置平台同步开关和报表接口。系统每天北京时间 10:00 同步前一天，14:00 和 22:00 同步当天；归档数据不会被覆盖。</p></div></div>
  <el-alert class="notice" type="info" :closable="false" show-icon><template #title>腾讯广告可复用现有腾讯业务单元级授权访问其获授权户号；如单个账户另配账户级凭证，则优先使用账户凭证。巨量引擎仍使用账户级凭证。凭证仅由服务端读取，页面不展示令牌明文。</template></el-alert>
  <div class="mapping-panel"><strong>腾讯营销字段对应</strong><div class="mapping-grid"><div><span>管理后台：消费</span><b>腾讯后台：花费</b></div><div><span>管理后台：展现</span><b>腾讯后台：曝光次数</b></div><div><span>管理后台：点击</span><b>腾讯后台：点击次数</b></div><div><span>管理后台：总表单</span><b>腾讯后台：目标转化量</b></div><div><span>管理后台：有效表单</span><b>腾讯后台：有效线索次数</b></div></div></div>
  <div class="cards" v-loading="loading"><el-card v-for="item in configs" :key="item.provider"><template #header><div class="card-title"><span>{{ providerName(item.provider) }}</span><el-tag :type="item.enabled?'success':'info'">{{ item.enabled?'已启用':'未启用' }}</el-tag></div></template><el-form :model="forms[item.provider]" label-width="112px"><el-form-item label="授权状态"><el-tag :type="hasCredentials(item)?'success':'warning'">{{hasCredentials(item)?'凭证已配置':'未配置凭证'}}</el-tag><span v-if="item.provider==='TENCENT_ADS'" class="credential-hint">业务单元授权；账户级凭证可覆盖</span><span v-else class="credential-hint">账户级授权</span></el-form-item><el-form-item label="启用自动同步"><el-switch v-model="forms[item.provider].enabled"/></el-form-item><el-form-item label="日报接口地址" required><el-input v-model="forms[item.provider].reportUrl"/></el-form-item><el-form-item label="最近同步"><span>{{ item.lastSyncedAt?new Date(item.lastSyncedAt).toLocaleString('zh-CN'):'尚未同步' }}</span></el-form-item><el-form-item v-if="item.lastSyncMessage" label="同步结果"><span class="sync-message">{{item.lastSyncMessage}}</span></el-form-item><el-form-item><div class="form-actions"><el-button type="primary" :loading="saving===item.provider" @click="save(item.provider)">保存设置</el-button><el-button :loading="testing===item.provider" @click="saveAndTest(item.provider)">保存并测试昨天</el-button></div></el-form-item></el-form></el-card></div>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { ElMessage } from 'element-plus';
import { getPromotionSyncConfigs, syncPromotionDailyMetrics, type PromotionDataSyncConfigItem, updatePromotionSyncConfig } from '../api/admin';
type Provider='TENCENT_ADS'|'OCEANENGINE';
const configs=ref<PromotionDataSyncConfigItem[]>([]);const loading=ref(false);const saving=ref('');const testing=ref('');const forms=reactive<Record<string,{enabled:boolean;reportUrl:string}>>({});
const providerName=(provider:string)=>provider==='TENCENT_ADS'?'腾讯营销':'巨量引擎';
const hasCredentials=(item:PromotionDataSyncConfigItem)=>Boolean(item.hasAccessToken||(item.clientId&&item.hasClientSecret&&item.hasRefreshToken));
async function load(){loading.value=true;try{configs.value=await getPromotionSyncConfigs();for(const item of configs.value)forms[item.provider]={enabled:item.enabled,reportUrl:item.reportUrl}}finally{loading.value=false}}
async function save(provider:Provider,quiet=false){const form=forms[provider];if(!form.reportUrl.trim())return ElMessage.warning('请填写日报接口地址');saving.value=provider;try{await updatePromotionSyncConfig({provider,...form});if(!quiet)ElMessage.success('同步设置已保存');await load()}finally{saving.value=''}}
async function saveAndTest(provider:Provider){const form=forms[provider];if(!form.reportUrl.trim())return ElMessage.warning('请填写日报接口地址');if(!form.enabled)return ElMessage.warning('请先开启自动同步');testing.value=provider;try{await save(provider,true);const date=new Date();date.setDate(date.getDate()-1);const statDate=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;const current=(await syncPromotionDailyMetrics({statDate,provider}))[0];if(current?.errors.length)ElMessage.error(current.errors.join('；'));else if(current?.noData)ElMessage.warning(`同步完成：成功 ${current.synced} 个账户，平台无数据 ${current.noData} 个账户`);else ElMessage.success(`测试成功，已同步 ${current?.synced||0} 个账户`);await load()}finally{testing.value=''}}
onMounted(load);
</script>
<style scoped>.page-heading{margin-bottom:18px}.page-title{margin:0 0 6px}.page-heading p{margin:0;color:var(--admin-text-muted)}.notice{margin-bottom:14px}.mapping-panel{margin-bottom:18px;padding:14px 16px;border:1px solid var(--admin-border);border-radius:12px;background:var(--el-fill-color-lighter)}.mapping-panel>strong{display:block;margin-bottom:10px;color:var(--admin-text)}.mapping-grid{display:grid;grid-template-columns:repeat(5,minmax(150px,1fr));gap:8px}.mapping-grid span,.mapping-grid b{display:block;padding:7px 9px;border-radius:7px;font-size:12px}.mapping-grid span{padding-bottom:2px;color:var(--admin-text-muted)}.mapping-grid b{padding-top:2px;color:var(--el-color-primary);font-weight:650}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(440px,1fr));gap:18px}.card-title{display:flex;align-items:center;justify-content:space-between}.form-actions{display:flex;gap:10px;flex-wrap:wrap}.form-actions :deep(.el-button){margin:0}.sync-message{line-height:1.7;color:var(--admin-text-muted)}.credential-hint{margin-left:10px;color:var(--admin-text-muted);font-size:12px}@media(max-width:900px){.mapping-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.cards{grid-template-columns:1fr}.mapping-grid{grid-template-columns:1fr}.form-actions{display:grid;grid-template-columns:1fr;width:100%}.form-actions :deep(.el-button){width:100%}}</style>
